import { describe, expect, it } from 'vitest';
import { STYLE_SUPPORT_GOLDEN } from '../generated/style-support-golden';
import { mockStyleSupport } from './widgets';

/** The mock imitates the engine's `style_support`; these are the engine's own values (generated by its test). */
describe('the mock style support', () => {
  it.each(['macos', 'windows', 'linux'] as const)('%s says what the engine says', (os) => {
    expect(mockStyleSupport(os)).toEqual(STYLE_SUPPORT_GOLDEN[os]);
  });
});
